parameters.jsCode:
const body = $json.body || $json;
const payload = body.payload || {};

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}

const eventType = cleanString(body.event || '');
const invitee = payload.invitee || {};
const scheduledEvent = payload.scheduled_event || {};

const inviteeEmail = cleanString(invitee.email || '');
const inviteeName = cleanString(invitee.name || '');
const startTime = cleanString(scheduledEvent.start_time || '');
const endTime = cleanString(scheduledEvent.end_time || '');
const eventName = cleanString(scheduledEvent.name || '');
const cancelUrl = cleanString(invitee.cancel_url || '');
const rescheduleUrl = cleanString(invitee.reschedule_url || '');

if (eventType !== 'invitee.created') {
  return [];
}

if (!inviteeEmail) {
  return [];
}

return {
  json: {
    event_type: eventType,
    invitee_email: inviteeEmail,
    invitee_name: inviteeName,
    start_time: startTime,
    end_time: endTime,
    event_name: eventName,
    cancel_url: cancelUrl,
    reschedule_url: rescheduleUrl,
    booked_at: new Date().toISOString()
  }
};

const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : [$json];
const prospect = rows[0] || {};

const ctx = $('Parse Calendly Event').first().json || {};

if (!prospect.prospect_id) {
  return [];
}

return {
  json: {
    prospect_id: prospect.prospect_id,
    target_email: prospect.target_email,
    current_status: prospect.status,
    invitee_email: ctx.invitee_email,
    invitee_name: ctx.invitee_name,
    start_time: ctx.start_time,
    end_time: ctx.end_time,
    event_name: ctx.event_name,
    cancel_url: ctx.cancel_url,
    reschedule_url: ctx.reschedule_url,
    booked_at: ctx.booked_at
  }
};

